head.script:
scwin.trigger1_onclick = function(e) {
    var title = "title" + Math.floor(Math.random() * 1000 + 1);
    //createWindow( title, iconURL, src, windowTitle, openAction, closeAction )
    windowContainer1.createWindow(title, null, "windowContainer_WEFF-410_(WSQ-3746)_child1_auto.xml", "");
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 필터를 적용하기위해 항목의 header를 클릭하여 필터값을 제외한다
    //2. To apply the filter, click the header of the entry to exclude the filter value.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('windowContainer1_subWindow0_wframe_trigger4').click()");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log1') == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    localStorage.removeItem("log");
    localStorage.removeItem("log1");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
